"""Title-only research checks; generated bytes are not playable native saves."""
from dataclasses import FrozenInstanceError, replace
from functools import lru_cache
import os
from pathlib import Path
import unittest

from koei_editor.games.dw3.models import SaveError
from koei_editor.research.berserk_aot import envelope
from koei_editor.research.berserk_pc import inspection
from tests.test_berserk_aot_envelopes import reference_envelope


@lru_cache(maxsize=1)
def procedural():
    payload = bytearray((bytes(range(256)) * 4956)[:1268508])
    # Independent observed generic header strings; no player bytes or revision.
    payload[:64] = b'BERSERK and the Band of the Hawk'.ljust(64, b'\0')
    payload[128:144] = b'Saved Data: 1'.ljust(16, b'\0')
    return reference_envelope(payload, 0x1234, 3), bytes(payload)


class BerserkInspectionTests(unittest.TestCase):
    def test_title_only_snapshot_is_immutable_and_noop_is_byte_exact(self):
        raw, payload = procedural()
        doc = inspection.inspect(bytearray(raw))
        self.assertEqual(doc.outer.payload, payload)
        self.assertEqual(inspection.reencode_unchanged(doc), raw)
        self.assertTrue(doc.title_matches)
        for name in ('revision_verified', 'all_integrity_verified', 'writable'):
            self.assertIs(getattr(doc, name), False)
        with self.assertRaises(FrozenInstanceError):
            doc.outer = None
        self.assertNotIn('payload', repr(doc))
        self.assertNotIn('raw', repr(doc))

    def test_valid_outer_sum_is_not_a_foreign_title_or_revision_gate(self):
        _, payload = procedural()
        for offset in (0, 32, 63, 128, 141, 143):
            damaged = bytearray(payload)
            damaged[offset] ^= 1
            raw = reference_envelope(damaged, 0x1234, 3)
            # A recomputed outer checksum cannot qualify the observed header.
            self.assertEqual(envelope.inspect(raw, profile='berserk').payload,
                             bytes(damaged))
            with self.subTest(offset=offset), self.assertRaises(SaveError):
                inspection.inspect(raw)

    def test_slot_label_is_not_interpreted_as_a_native_revision(self):
        _, payload = procedural()
        changed = bytearray(payload)
        changed[140] = ord('2')
        with self.assertRaisesRegex(SaveError, 'slot-one'):
            inspection.inspect(reference_envelope(changed, 0x1234, 3))

    def test_cipher_corruption_truncation_and_untrusted_input_rejected(self):
        raw, _ = procedural()
        for offset in (0, 2, 4, len(raw) - 1):
            damaged = bytearray(raw)
            damaged[offset] ^= 1
            with self.subTest(offset=offset), self.assertRaises(SaveError):
                inspection.inspect(damaged)
        for value in (raw[:-1], raw + b'x', b'', True, None, 1268512):
            with self.subTest(type=type(value)), self.assertRaises(SaveError):
                inspection.inspect(value)

    def test_forged_snapshot_and_replacement_payload_are_rejected(self):
        raw, payload = procedural()
        doc = inspection.inspect(raw)
        forged = replace(doc, outer=replace(doc.outer, payload=b'x' + payload[1:]))
        for value in (forged, doc.outer, None, raw):
            with self.subTest(type=type(value)), self.assertRaises(SaveError):
                inspection.reencode_unchanged(value)
        with self.assertRaises(TypeError):
            inspection.reencode_unchanged(doc, payload)

    def test_no_gameplay_fields_file_operations_or_registration(self):
        from koei_editor.game_registry import GAMES
        for name in ('read_save', 'fields_for', 'stage', 'review', 'serialize',
                     'save_as', 'restore', 'backup', 'maximums'):
            self.assertFalse(hasattr(inspection, name))
        self.assertNotIn('berserk_pc', GAMES)

    def test_foreign_profile_cannot_forge_a_berserk_snapshot(self):
        # A title string must not promote a different selected sample profile.
        payload = bytearray(769564)
        payload[:64] = b'BERSERK and the Band of the Hawk'.ljust(64, b'\0')
        payload[128:144] = b'Saved Data: 1'.ljust(16, b'\0')
        raw = reference_envelope(payload, 0x1234, 3)
        foreign = envelope.inspect(raw, profile='aot1')
        with self.assertRaises(SaveError):
            inspection.inspect(raw)
        with self.assertRaisesRegex(SaveError, 'Berserk outer envelope profile'):
            inspection.reencode_unchanged(inspection.Inspection(foreign))


class OptionalNativeBerserkInspectionTests(unittest.TestCase):
    def test_reviewed_complete_native_corpus(self):
        location = os.environ.get('BERSERK_PC_NATIVE_DIR')
        if not location:
            self.skipTest('No reviewed native corpus supplied through BERSERK_PC_NATIVE_DIR')
        paths = sorted(Path(location).glob('*.dat'))
        self.assertTrue(paths, 'The supplied native corpus contains no flat .dat files')
        for index, path in enumerate(paths):
            with self.subTest(sample=index):
                with path.open('rb') as source:
                    raw = source.read(1268513)
                doc = inspection.inspect(raw)
                self.assertEqual(inspection.reencode_unchanged(doc), raw)
                self.assertIs(doc.writable, False)
                self.assertIs(doc.all_integrity_verified, False)


if __name__ == '__main__':
    unittest.main()
